Slack.RequestContext requestContext = new Slack.RequestContext();
Slack.ActionDispatcher actionDispatcher = new Slack.ActionDispatcher();
System.assertEquals(false, actionDispatcher.allowUnauthenticatedUsers());
actionDispatcher.invoke(new Map<String,Object>{'action' => 'clicked'}, requestContext);
System.assert(JSON.serialize(actionDispatcher).contains('"invocationCount":1'));
System.assert(JSON.serialize(actionDispatcher).contains('"lastMethod":"invoke"'));
Slack.EventDispatcher eventDispatcher = new Slack.EventDispatcher();
eventDispatcher.invoke(new Slack.EventParameters(new Slack.Event(), 'team', 1), requestContext);
System.assert(JSON.serialize(eventDispatcher).contains('"invocationCount":1'));
Slack.ShortcutDispatcher shortcutDispatcher = new Slack.ShortcutDispatcher();
shortcutDispatcher.invoke(new Slack.ShortcutParameters('shortcut'), requestContext);
System.assert(JSON.serialize(shortcutDispatcher).contains('"invocationCount":1'));
Slack.SlashCommandDispatcher slashDispatcher = new Slack.SlashCommandDispatcher();
slashDispatcher.invoke(new Slack.SlashCommandParameters('/local', 'payload'), requestContext);
System.assert(JSON.serialize(slashDispatcher).contains('"invocationCount":1'));
Slack.RunnableHandler handler = new Slack.RunnableHandler();
handler.run();
System.assert(JSON.serialize(handler).contains('"ran":true'));
Slack.UserMappingUrlServiceProvider urls = new Slack.UserMappingUrlServiceProvider();
String slackUrl = urls.generateSlackAuthorizationUrl('state-1');
System.assert(slackUrl.contains('state=state-1'));
String partnerUrl = urls.generatePartnerAuthorizationUrl('partner-a', 'state-2');
System.assert(partnerUrl.contains('partner=partner-a'));
System.assert(partnerUrl.contains('state=state-2'));
Slack.UserProvisioningProvider provisioning = new Slack.UserProvisioningProvider();
Object imported = provisioning.importUsers(new List<Slack.UserMapping>{new Slack.UserMapping('005000000000001', 'U1')}, 'team-a');
String importJson = JSON.serialize(imported);
System.assert(importJson.contains('"action":"importUsers"'));
System.assert(importJson.contains('"teamId":"team-a"'));
Object sfRevoked = provisioning.revokeUsersBySalesforceId(new List<String>{'005000000000001'}, 'team-b');
System.assert(JSON.serialize(sfRevoked).contains('"action":"revokeUsersBySalesforceId"'));
Object slackRevoked = provisioning.revokeUsersBySlackId(new List<String>{'U1'});
System.assert(JSON.serialize(slackRevoked).contains('"action":"revokeUsersBySlackId"'));
Slack.State state = new Slack.State();
Slack.TestHarness.Enterprise enterprise = state.createEnterprise('E1', 'Example');
Slack.TestHarness.Team team = state.createTeam('example', enterprise);
Slack.TestHarness.User user = state.createUser('U1', 'M User', team, 'en_US');
Slack.TestHarness.User other = state.createUser('U2', 'Other User', team, 'en_US');
Slack.TestHarness.Channel channel = state.createPublicChannel(team, 'general', 'en_US');
Slack.TestHarness.UserSession session = state.createUserSession(user, channel);
channel.addUser(user);
Slack.TestHarness.Message message = channel.sendMessage(session, 'hello');
System.assertEquals(true, message.canBeSeenByUser(user));
System.assertEquals(false, message.canBeSeenByUser(other));

